package com.example.meetomxh;

import android.content.ContentResolver;
import android.content.Intent;
import android.database.Cursor;
import android.media.MediaCodec;
import android.media.MediaExtractor;
import android.media.MediaFormat;
import android.media.MediaMetadataRetriever;
import android.media.MediaMuxer;
import android.net.Uri;
import android.os.Bundle;
import android.provider.OpenableColumns;
import android.view.View;
import android.widget.*;
import androidx.activity.result.ActivityResultLauncher;
import androidx.activity.result.PickVisualMediaRequest;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.annotation.Nullable;
import androidx.appcompat.app.AppCompatActivity;
import com.example.meetomxh.storage.SupabaseStorage;
import com.example.meetomxh.supabase.*;
import org.json.JSONObject;
import java.io.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/** Basic local trim, mute, cover selection and verified upload for short MP4 posts. */
public final class CreateReelActivity extends AppCompatActivity {
    private static final long MAX_BYTES=50L*1024*1024,MAX_DURATION_MS=60_000;
    private VideoView preview;private SeekBar startBar,endBar,coverBar;private CheckBox mute;private ImageView cover;
    private EditText caption;private Spinner audience;private ProgressBar uploadProgress;private TextView status;private Button publish;
    private ActivityResultLauncher<PickVisualMediaRequest> picker;private final ExecutorService work=Executors.newSingleThreadExecutor();
    private File sourceFile,editedFile;private long sourceDurationMs;private int startMs,endMs,coverMs,trimActualStartMs,uploadDurationMs,uploadCoverMs;private String uploadedAsset,uploadedCoverAsset;private SupabaseStorage.Transfer transfer;private boolean busy;
    private final android.os.Handler main=new android.os.Handler(android.os.Looper.getMainLooper());
    private final Runnable coverUpdate=()->extractCover();

    @Override protected void onCreate(@Nullable Bundle saved){super.onCreate(saved);setContentView(R.layout.activity_reel_create);
        preview=findViewById(R.id.reel_preview);startBar=findViewById(R.id.reel_trim_start);endBar=findViewById(R.id.reel_trim_end);coverBar=findViewById(R.id.reel_cover_position);mute=findViewById(R.id.reel_mute_audio);cover=findViewById(R.id.reel_cover_preview);caption=findViewById(R.id.reel_caption);audience=findViewById(R.id.reel_audience);uploadProgress=findViewById(R.id.reel_upload_progress);status=findViewById(R.id.reel_status);publish=findViewById(R.id.reel_publish);
        ArrayAdapter<String> choices=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Công khai","Bạn bè","Chỉ mình tôi"});audience.setAdapter(choices);
        picker=registerForActivityResult(new ActivityResultContracts.PickVisualMedia(),uri->{if(uri!=null)stage(uri);});
        findViewById(R.id.reel_pick_video).setOnClickListener(v->picker.launch(new PickVisualMediaRequest.Builder().setMediaType(ActivityResultContracts.PickVisualMedia.VideoOnly.INSTANCE).build()));
        startBar.setOnSeekBarChangeListener(new RangeListener(true));endBar.setOnSeekBarChangeListener(new RangeListener(false));coverBar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int p,boolean user){if(user){coverMs=p;queueCover();preview.seekTo(startMs+p);}}});
        publish.setOnClickListener(v->submit());findViewById(R.id.reel_trim_label).setContentDescription("Video được cắt ở ranh giới khung hình khóa gần nhất");
    }
    private final class RangeListener implements SeekBar.OnSeekBarChangeListener {final boolean first;RangeListener(boolean value){first=value;}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int p,boolean user){if(!user||sourceFile==null)return;if(first){startMs=Math.min(p,Math.max(0,endMs-1000));if(endMs-startMs>MAX_DURATION_MS)startMs=endMs-(int)MAX_DURATION_MS;startBar.setProgress(startMs);}else{endMs=Math.max(p,startMs+1000);if(endMs-startMs>MAX_DURATION_MS)endMs=startMs+(int)MAX_DURATION_MS;endBar.setProgress(endMs);}coverBar.setMax(Math.max(1,endMs-startMs));coverMs=Math.min(coverMs,endMs-startMs);coverBar.setProgress(coverMs);preview.seekTo(startMs);}}
    private void stage(Uri uri){if(busy)return;String type=getContentResolver().getType(uri);if(type==null||!"video/mp4".equalsIgnoreCase(type)){status.setText("Chọn video MP4.");return;}busy=true;publish.setEnabled(false);status.setText("Đang kiểm tra video…");work.execute(()->{File staged=null;try{staged=copy(uri);MediaMetadataRetriever r=new MediaMetadataRetriever();r.setDataSource(staged.getAbsolutePath());String d=r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION);long duration=Long.parseLong(d);r.release();if(duration<1000)throw new IOException("Video phải dài ít nhất 1 giây.");File finalStaged=staged;main.post(()->{if(isFinishing()){finalStaged.delete();return;}if(sourceFile!=null)sourceFile.delete();if(editedFile!=null)editedFile.delete();sourceFile=finalStaged;editedFile=null;uploadedAsset=null;uploadedCoverAsset=null;setEditorEnabled(true);uploadDurationMs=0;uploadCoverMs=0;trimActualStartMs=0;sourceDurationMs=duration;startMs=0;endMs=(int)Math.min(duration,MAX_DURATION_MS);coverMs=0;startBar.setMax((int)duration);startBar.setProgress(0);endBar.setMax((int)duration);endBar.setProgress(endMs);coverBar.setMax(endMs);coverBar.setProgress(0);preview.setVideoURI(Uri.fromFile(sourceFile));preview.setOnPreparedListener(mp->{mp.setLooping(true);mp.start();});publish.setEnabled(true);busy=false;status.setText(String.format(Locale.ROOT,"%.1f giây · %.1f MiB",duration/1000f,sourceFile.length()/1048576f));queueCover();});}catch(Exception e){if(staged!=null)staged.delete();main.post(()->{busy=false;publish.setEnabled(true);status.setText(e.getMessage()==null?"Không đọc được video.":e.getMessage());});}});}
    private File copy(Uri uri)throws Exception{File out=File.createTempFile("meeto-reel-source-",".mp4",getCacheDir());try(InputStream in=getContentResolver().openInputStream(uri);OutputStream stream=new FileOutputStream(out)){if(in==null)throw new IOException("Không đọc được video.");byte[] b=new byte[32768];long total=0;int n;while((n=in.read(b))!=-1){total+=n;if(total>MAX_BYTES)throw new IOException("Video tối đa 50 MiB.");stream.write(b,0,n);}}if(out.length()<12)throw new IOException("File MP4 không hợp lệ.");try(RandomAccessFile f=new RandomAccessFile(out,"r")){f.seek(4);byte[] t=new byte[4];f.readFully(t);if(t[0]!='f'||t[1]!='t'||t[2]!='y'||t[3]!='p')throw new IOException("File không phải MP4 hợp lệ.");}return out;}
    private void queueCover(){main.removeCallbacks(coverUpdate);main.postDelayed(coverUpdate,220);}
    private void extractCover(){if(sourceFile==null)return;File file=sourceFile;long at=(long)startMs+coverMs;work.execute(()->{MediaMetadataRetriever r=new MediaMetadataRetriever();android.graphics.Bitmap b=null;try{r.setDataSource(file.getAbsolutePath());b=r.getFrameAtTime(at*1000L,MediaMetadataRetriever.OPTION_CLOSEST_SYNC);}catch(Exception ignored){}finally{try{r.release();}catch(Exception ignored){}}android.graphics.Bitmap frame=b;if(frame!=null)main.post(()->{if(!isFinishing()&&sourceFile==file)cover.setImageBitmap(frame);else frame.recycle();});});}
    private void submit(){if(busy)return;if(sourceFile==null){status.setText("Trước tiên hãy chọn video MP4.");return;}if(endMs<=startMs||endMs-startMs>MAX_DURATION_MS){status.setText("Chọn đoạn video dài từ 1 đến 60 giây.");return;}busy=true;publish.setEnabled(false);status.setText("Đang cắt và chuẩn bị video…");if(uploadedAsset!=null){if(uploadedCoverAsset==null)uploadCover(uploadDurationMs);else create(uploadDurationMs);return;}final boolean muteAudio=mute.isChecked();work.execute(()->{try{File result;if(startMs==0&&endMs>=sourceDurationMs&& !muteAudio)result=sourceFile;else result=trim(sourceFile,startMs,endMs,muteAudio);if(result.length()>MAX_BYTES)throw new IOException("Video đã chỉnh sửa vượt 50 MiB.");MediaMetadataRetriever metadata=new MediaMetadataRetriever();metadata.setDataSource(result.getAbsolutePath());int duration=(int)Long.parseLong(metadata.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));metadata.release();int coverOffset=Math.max(0,Math.min(duration,startMs+coverMs-trimActualStartMs));File ready=result;int finalDuration=duration;main.post(()->{if(isFinishing())return;editedFile=ready;uploadDurationMs=finalDuration;uploadCoverMs=coverOffset;upload(ready,finalDuration);});}catch(Exception e){main.post(()->{busy=false;publish.setEnabled(true);status.setText("Không thể cắt video: "+(e.getMessage()==null?"định dạng không hỗ trợ":e.getMessage()));});}});}
    private File trim(File input,int fromMs,int toMs,boolean muted)throws Exception{MediaExtractor probe=new MediaExtractor();probe.setDataSource(input.getAbsolutePath());int video=-1;for(int i=0;i<probe.getTrackCount();i++)if(probe.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith("video/")){video=i;break;}if(video<0){probe.release();throw new IOException("Không tìm thấy video track.");}probe.selectTrack(video);long requested=(long)fromMs*1000L;probe.seekTo(requested,MediaExtractor.SEEK_TO_PREVIOUS_SYNC);long actualStart=probe.getSampleTime();probe.release();if(actualStart<0)actualStart=requested;trimActualStartMs=(int)(actualStart/1000L);long end=(long)toMs*1000L;if(end-actualStart>60_000_000L)throw new IOException("Điểm cắt theo keyframe vượt quá 60 giây; hãy chỉnh điểm bắt đầu.");return trimMux(input,actualStart,end,muted);}    private File trimMux(File input,long actualStart,long end,boolean muted)throws Exception{MediaExtractor ex=new MediaExtractor();ex.setDataSource(input.getAbsolutePath());File output=File.createTempFile("meeto-reel-edit-",".mp4",getCacheDir());MediaMuxer muxer=new MediaMuxer(output.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);int[] map=new int[ex.getTrackCount()];Arrays.fill(map,-1);try{int orientation=0;MediaMetadataRetriever meta=new MediaMetadataRetriever();meta.setDataSource(input.getAbsolutePath());try{orientation=Integer.parseInt(meta.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION));}catch(Exception ignored){}meta.release();for(int i=0;i<ex.getTrackCount();i++){MediaFormat f=ex.getTrackFormat(i);String mime=f.getString(MediaFormat.KEY_MIME);if(mime.startsWith("video/")||(!muted&&mime.startsWith("audio/")))map[i]=muxer.addTrack(f);}if(orientation!=0)muxer.setOrientationHint(orientation);muxer.start();ex.seekTo(actualStart,MediaExtractor.SEEK_TO_PREVIOUS_SYNC);ByteBuffer buffer=ByteBuffer.allocate(4*1024*1024);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(true){int track=ex.getSampleTrackIndex();if(track<0)break;long time=ex.getSampleTime();if(time>=end)break;if(time>=actualStart&&map[track]>=0){buffer.clear();int size=ex.readSampleData(buffer,0);if(size<0)break;info.offset=0;info.size=size;info.presentationTimeUs=Math.max(0,time-actualStart);info.flags=ex.getSampleFlags();muxer.writeSampleData(map[track],buffer,info);}if(!ex.advance())break;}muxer.stop();return output;}catch(Exception e){output.delete();throw e;}finally{ex.release();try{muxer.release();}catch(Exception ignored){}}}
    private void upload(File file,int duration){setEditorEnabled(false);status.setText("Đang tải video lên…");uploadProgress.setVisibility(View.VISIBLE);uploadProgress.setProgress(0);transfer=SupabaseStorage.uploadVideo(getContentResolver(),file,"posts",SessionManager.getInstance().uid(),new SupabaseStorage.UploadListener(){public void onProgress(int p){uploadProgress.setProgress(p);}public void onFailure(String error){busy=false;publish.setEnabled(true);setEditorEnabled(true);status.setText("Tải lên thất bại. Caption và chỉnh sửa vẫn được giữ. "+error+" Có thể thử lại.");transfer=null;}public void onSuccess(String ref){uploadedAsset=ref;uploadDurationMs=duration;uploadCover(duration);}});}
    private void uploadCover(int duration){status.setText("Đang lưu ảnh bìa…");work.execute(()->{File image=null;try{MediaMetadataRetriever r=new MediaMetadataRetriever();r.setDataSource(editedFile.getAbsolutePath());android.graphics.Bitmap bitmap=r.getFrameAtTime((long)uploadCoverMs*1000L,MediaMetadataRetriever.OPTION_CLOSEST_SYNC);r.release();if(bitmap==null)throw new IOException("Không đọc được khung ảnh bìa.");int max=960,largest=Math.max(bitmap.getWidth(),bitmap.getHeight());if(largest>max){float scale=max/(float)largest;android.graphics.Bitmap smaller=android.graphics.Bitmap.createScaledBitmap(bitmap,Math.max(1,(int)(bitmap.getWidth()*scale)),Math.max(1,(int)(bitmap.getHeight()*scale)),true);if(smaller!=bitmap)bitmap.recycle();bitmap=smaller;}image=File.createTempFile("meeto-reel-cover-",".jpg",getCacheDir());try(FileOutputStream out=new FileOutputStream(image)){bitmap.compress(android.graphics.Bitmap.CompressFormat.JPEG,86,out);}bitmap.recycle();File ready=image;main.post(()->{transfer=SupabaseStorage.uploadImage(getContentResolver(),ready,"posts",SessionManager.getInstance().uid(),new SupabaseStorage.UploadListener(){public void onProgress(int p){uploadProgress.setProgress(p);}public void onFailure(String e){ready.delete();transfer=null;busy=false;publish.setEnabled(true);status.setText("Video tải lên rồi; ảnh bìa chưa tải được. Nhấn đăng lại để thử tiếp. "+e);}public void onSuccess(String ref){ready.delete();uploadedCoverAsset=ref;create(duration);}});});}catch(Exception e){if(image!=null)image.delete();main.post(()->{busy=false;publish.setEnabled(true);status.setText("Không tạo được ảnh bìa. Có thể thử đăng lại. "+(e.getMessage()==null?"":e.getMessage()));});}});}
    private void setEditorEnabled(boolean enabled){findViewById(R.id.reel_pick_video).setEnabled(enabled);startBar.setEnabled(enabled);endBar.setEnabled(enabled);coverBar.setEnabled(enabled);mute.setEnabled(enabled);caption.setEnabled(enabled);audience.setEnabled(enabled);}
    private void create(int duration){status.setText("Đang đăng Reel…");String target=audience.getSelectedItemPosition()==1?"friends":audience.getSelectedItemPosition()==2?"private":"public";String text=caption.getText().toString();String fingerprint=uploadedAsset+"|"+text+"|"+target+"|"+duration+"|"+uploadCoverMs;String request=RequestIds.get("create_reel",fingerprint);Api.run(()->{JSONObject result=RpcClient.object("create_reel",Api.obj("p_video_asset_id",Dto.assetId(uploadedAsset),"p_cover_asset_id",Dto.assetId(uploadedCoverAsset),"p_caption",text,"p_audience",target,"p_duration_ms",duration,"p_cover_position_ms",Math.min(uploadCoverMs,duration),"p_client_request_id",request));RequestIds.complete("create_reel",fingerprint);return result;},new Api.Callback<JSONObject>(){public void success(JSONObject r){busy=false;uploadProgress.setVisibility(View.GONE);status.setText("Reel đã được đăng.");com.example.meetomxh.repositories.ReelsRepository.invalidate();setResult(RESULT_OK);finish();}public void error(String e){busy=false;publish.setEnabled(true);status.setText("Video đã tải lên nhưng chưa đăng. Caption được giữ; nhấn đăng lại để tiếp tục. "+e);}});}
    private final class Unused { }
    @Override protected void onDestroy(){main.removeCallbacks(coverUpdate);if(transfer!=null)transfer.cancel();if(preview!=null)preview.stopPlayback();if(sourceFile!=null)sourceFile.delete();if(editedFile!=null&&editedFile!=sourceFile)editedFile.delete();work.shutdownNow();super.onDestroy();}
}
